import {business, services, products, faqs} from './data.js';
const $=(s,c=document)=>c.querySelector(s), $$=(s,c=document)=>[...c.querySelectorAll(s)];
const arrow='<span class="arrow" aria-hidden="true">↗</span>';
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const booking=(id='',label='Book a Repair',cls='btn')=>`<a class="${cls}" href="/contact${id?'?service='+encodeURIComponent(id):''}">${label}${arrow}</a>`;
const image=(file,alt,cls='',eager=false)=>`<div class="${cls}"><img src="/assets/${file}" alt="${alt}" ${eager?'fetchpriority="high"':'loading="lazy"'}></div>`;
const eyebrow=t=>`<div class="eyebrow">${t}</div>`;
const logo=()=>`<a href="/" class="logo" aria-label="Port and Pixel home"><span class="logo-mark" aria-hidden="true"></span><span class="wordmark">port <em>&</em> pixel<span style="color:var(--brand)">.</span></span></a>`;
const links=[['/services','Services'],['/accessories','Accessories'],['/pricing','Pricing Guide'],['/contact','Contact']];
const path=location.pathname.replace(/\/$/,'')||'/';
const navLink=([url,text])=>`<a href="${url}" ${path===url?'class="active" aria-current="page"':''}>${text}</a>`;
function header(){return `<div class="topbar">A little care. A longer life for your phone.<span> / </span>Repairs & everyday essentials</div><header class="header"><div class="wrap nav">${logo()}<nav class="desktop-links" aria-label="Main navigation"><details class="home-menu"><summary class="${['/','/home-2'].includes(path)?'active':''}">Home <span aria-hidden="true">⌄</span></summary><div class="dropdown"><a href="/" ${path==='/'?'aria-current="page"':''}>Home 1</a><a href="/home-2" ${path==='/home-2'?'aria-current="page"':''}>Home 2</a></div></details>${links.map(navLink).join('')}</nav><div class="nav-tools"><button class="icon-btn theme-toggle" aria-label="Toggle dark mode">◐</button><button class="icon-btn direction-btn" aria-label="Switch text direction">RTL</button>${booking()}</div><button class="menu-toggle" aria-expanded="false" aria-controls="mobile-nav" aria-label="Open navigation">☰</button></div><nav id="mobile-nav" class="mobile-panel" aria-label="Mobile navigation" inert><details><summary>Home <span aria-hidden="true">⌄</span></summary><div class="mobile-homes"><a href="/">Home 1 — The studio</a><a href="/home-2">Home 2 — Find your fix</a></div></details>${links.map(navLink).join('')}<div class="mobile-tools"><button class="btn secondary theme-toggle">Toggle theme ◐</button><button class="btn secondary direction-btn">RTL</button></div>${booking()}</nav></header>`}
function footer(){return `<section class="closing"><div class="wrap closing-inner"><div><h2>Back to working.<br>Back to your day.</h2><p>Tell us what’s going on. We’ll help you find the next step.</p></div>${booking()}</div></section><footer class="footer"><div class="wrap footer-grid"><div class="footer-brand">${logo()}<p>Thoughtful repairs. Useful accessories.<br>A little more life for the phone you love.</p></div><div><h4>Explore the studio</h4><div class="footer-links"><a href="/">Home 1</a><a href="/home-2">Home 2</a><a href="/services">Our services</a></div></div><div><h4>Here to help</h4><div class="footer-links"><a href="/accessories">Accessories</a><a href="/pricing">Pricing guide</a><a href="/contact">Contact & booking</a><button class="privacy-open" style="text-align:start;background:none;border:0;padding:0;color:inherit;font:inherit">Privacy & your request</button></div></div><div><h4>Let’s start with your device.</h4><p class="small">A clear description makes a helpful first step.</p><a class="text-link" style="margin-top:16px" href="/contact">Prepare a repair request ${arrow}</a>${business.phone?`<p><a href="tel:${safe(business.phone)}">${safe(business.phone)}</a></p>`:''}${business.email?`<p><a href="mailto:${safe(business.email)}">${safe(business.email)}</a></p>`:''}${business.address?`<p>${safe(business.address)}</p>`:''}${business.hours?`<p>${safe(business.hours)}</p>`:''}</div></div><div class="wrap footer-end"><span>© ${new Date().getFullYear()} Port & Pixel. A better next chapter.</span><button class="back-top">Back to top ↑</button></div></footer><dialog id="detail-modal" aria-label="Accessory details"><div class="modal-inner"><button class="modal-close" aria-label="Close details">×</button><div id="modal-content"></div></div></dialog><dialog id="privacy-modal" aria-labelledby="privacy-title"><div class="modal-inner"><button class="modal-close" aria-label="Close privacy information">×</button><h2 id="privacy-title">Your request. Your information.</h2><div class="privacy-copy"><p>With no submission service configured, form entries stay in this page’s memory and are not sent to the shop. You can download a copy to your own device. Refreshing clears the form.</p><p style="margin-top:15px">Theme and reading direction are saved in your browser. We do not ask for device passcodes or payment details. Do not include passwords, financial information, or other sensitive content in your issue description.</p></div></div></dialog>`}
const promises=()=>`<div class="wrap promise-strip">${[['⌕','Thoughtful diagnosis','Understand the issue first'],['≡','Clear estimates','Know before you go ahead'],['◇','Handled with care','Attention to the little things'],['◷','Same-day options','For eligible repairs & available parts']].map(([icon,title,copy])=>`<div class="promise"><span aria-hidden="true">${icon}</span><div><strong>${title}</strong><p>${copy}</p></div></div>`).join('')}</div>`;
const productCard=p=>`<article class="product-card">${image(p.image,p.name,'product-image')}<h3>${p.name}</h3><p>${p.attribute}</p><div class="product-buttons"><a class="text-link" href="/contact?product=${p.id}">Enquire about this item ${arrow}</a><button data-product="${p.id}" aria-label="View ${p.name} details">Details</button></div></article>`;
const accordion=(items=faqs)=>items.map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join('');
const faqSection=(title='A few things you might be wondering.',items=faqs)=>`<section class="section"><div class="wrap faq-layout"><div>${eyebrow('Good to know')}<h2>${title}</h2></div><div>${accordion(items)}</div></div></section>`;
const workflow=()=>`<section class="workflow"><div class="wrap">${eyebrow('From first hello to fully connected')}<h2>A clear process.<br>At every step.</h2><div class="steps">${[['Tell us the issue','Share your device model and what isn’t working.'],['Get a clear estimate','Understand the proposed work before deciding.'],['Bring in your device','Agree on a visit and prepare your phone.'],['Repair and collection','We discuss the outcome and next steps with you.']].map(([t,p],i)=>`<div class="step"><span>0${i+1} /</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section>`;
function home(){return `<section class="hero"><div class="wrap hero-grid"><div class="hero-copy">${eyebrow('Good phones deserve another chapter')}<h1>Your phone isn’t<br>finished. It just<br>needs <em>the right fix.</em></h1><p>A cracked screen. A tired battery. A connection that won’t quite connect. Let’s get your everyday essential back to its best.</p><div class="actions">${booking()}<a class="btn secondary" href="/services">Explore Services ${arrow}</a></div><div class="hero-note"><i></i>Careful repairs. Clear conversations. No guesswork.</div></div><div class="hero-visual">${image('repair.jpg','Technician carefully working on an opened smartphone with precision tools','hero-photo',true)}<span class="photo-caption">PRECISION IN THE DETAILS</span><div class="ticket"><div class="ticket-top"><span>PORT & PIXEL / SERVICE NOTE</span><span>01—06</span></div><div class="ticket-main"><span class="ticket-icon" aria-hidden="true">✓</span><div><strong>A better next chapter.</strong><p>Repair first. Replace only if needed.</p></div></div></div><span class="visual-index">SMALL PARTS. BIG DIFFERENCE.</span></div></div></section>${promises()}<section class="fix-section"><div class="wrap fix-grid"><div class="fix-intro">${eyebrow('01 / Let’s narrow it down')}<h2>What’s not<br>working for you?</h2><p>No technical terms needed. Pick the problem that sounds most familiar.</p><div class="issue-buttons">${services.map((s,i)=>`<button class="issue-button" data-issue="${s.id}" aria-pressed="${i===0}"><span aria-hidden="true">${s.icon}</span><span>${s.short}</span></button>`).join('')}</div></div><div class="fix-panel" id="issue-panel" aria-live="polite">${issuePanel(services[0])}</div></div></section><section class="section"><div class="wrap"><div class="section-head"><div>${eyebrow('02 / The right attention')}<h2>Little problems.<br>Thoughtful solutions.</h2></div><a href="/services" class="text-link">All repair services ${arrow}</a></div><div class="feature-grid"><div class="feature-photo"><img loading="lazy" src="/assets/screen-repair.jpg" alt="Close-up of a smartphone being serviced"><div class="feature-overlay"><h3>A fresh start for your screen.</h3><p>Cracks, flickers, and unresponsive displays. Let’s take a closer look.</p><a href="/services#screen">Explore screen repairs ${arrow}</a></div></div><div>${services.slice(1,4).map(s=>`<a class="service-row" href="/services#${s.id}"><span aria-hidden="true">${s.icon}</span><div><h3>${s.name}</h3><p>${s.tag}</p></div>${arrow}</a>`).join('')}</div></div></div></section>${workflow()}<section class="section"><div class="wrap approach-grid">${image('workshop.jpg','Technician inspecting a device at a precision repair workbench','approach-photo')}<div class="approach-copy">${eyebrow('A little care goes a long way')}<h2>Your everyday.<br>Our attention to detail.</h2><p>Your phone holds the things that keep your day moving. We think looking after it should feel straightforward, considered, and personal.</p>${[['Look closer, first.','Careful checks help us understand the issue before recommending a repair.'],['Keep you in the picture.','Clear explanations and a device-specific estimate, so you can make an informed choice.'],['Respect what’s yours.','Thoughtful handling and practical advice to help you prepare your device for service.']].map(([t,p])=>`<div class="approach-point"><span aria-hidden="true">✓</span><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></div></section><section class="section" style="padding-top:10px"><div class="wrap"><div class="section-head"><div>${eyebrow('03 / The everyday extras')}<h2>Good company for your phone.</h2></div><a href="/accessories" class="text-link">Browse Accessories ${arrow}</a></div><div class="products-preview">${products.slice(0,4).map(productCard).join('')}</div></div></section><section class="price-preview"><div class="wrap price-grid"><div>${eyebrow('No surprises. Just clarity.')}<h2>Let’s talk about<br>the right estimate.</h2><p>Every model is a little different. Get to know what affects repair costs before you make a decision.</p><a href="/pricing" class="text-link" style="margin-top:25px">View Pricing Guide ${arrow}</a></div><div>${services.slice(0,4).map(s=>`<a class="price-line" href="/pricing?service=${s.id}"><strong>${s.name}</strong><span>Device-specific estimate ${arrow}</span></a>`).join('')}<p class="small" style="margin-top:17px">Final scope and cost are confirmed after assessment.</p></div></div></section>`}
function issuePanel(s){return `<div class="panel-kicker"><span>YOUR NEXT STEP</span><span>${s.icon} / ${s.id.toUpperCase()}</span></div><h3>${s.name}</h3><p>${s.detail}</p><p class="symptom"><strong>Sound familiar?</strong><br>${s.symptoms}</p><p><strong>What happens next</strong><br>Share your device model. We’ll start with an assessment and explain the options.</p>${booking(s.id,'Let’s fix this','text-link')}`}
function home2(){return `<section class="finder-hero"><div class="wrap"><div class="finder-hero-top"><div>${eyebrow('A simpler way to your next step')}<h1>Let’s figure out<br>what’s wrong<br>with your phone.</h1><p>You know your phone. Tell us what feels different, and we’ll point you toward a relevant service.</p></div>${image('finder.jpg','A precision electronics circuit board up close','finder-hero-photo',true)}</div><div class="finder" id="repair-finder"><div class="finder-fields"><div><label for="finder-device"><span>01</span>Your device</label><select id="finder-device"><option>Smartphone</option><option>Tablet</option><option>Other mobile device</option></select></div><div><label for="finder-problem"><span>02</span>The problem</label><select id="finder-problem">${services.map(s=>`<option value="${s.id}">${s.short}</option>`).join('')}</select></div><div><label for="finder-symptom"><span>03</span>What you’re noticing</label><select id="finder-symptom"></select></div></div><div id="finder-result" aria-live="polite"></div></div><p class="small" style="margin-top:14px">A guide to our services, rather than an automatic diagnosis. Inspection is needed to confirm a fault. Device support is subject to confirmation.</p></div></section><section class="section"><div class="wrap"><div class="section-head"><div>${eyebrow('Start with the symptom')}<h2>Sound familiar?</h2></div><p>Everyday frustrations.<br>A clear place to start.</p></div><div class="problem-list">${[['Battery drains too quickly','battery'],['Phone will not charge','charging'],['Cracked or unresponsive display','screen'],['Camera won’t focus','camera'],['Phone running slowly','software'],['Speaker audio sounds distorted','audio']].map(([t,id])=>`<a href="/services#${id}">${t}${arrow}</a>`).join('')}</div></div></section><section class="spotlight"><img loading="lazy" src="/assets/spotlight.jpg" alt="Detailed hands-on electronics repair"><div class="wrap spotlight-inner">${eyebrow('On the workbench / Battery care')}<h2>A tired battery doesn’t have to mean a new phone.</h2><p>Shorter days between charges can have several causes. A battery health check helps establish whether replacement is the right next step.</p><div class="actions">${booking('battery','Explore battery service','btn light')}</div></div></section><section class="section"><div class="wrap"><div class="section-head"><div>${eyebrow('Ready for the everyday')}<h2>The small things that help.</h2></div><a href="/accessories" class="text-link">Explore essentials ${arrow}</a></div><div class="essentials-list">${[products[0],products[1],products[5]].map(p=>`<a href="/contact?product=${p.id}">${image(p.image,p.name,'product-image')}<div><h3>${p.name}</h3><p>Ask about compatibility ${arrow}</p></div></a>`).join('')}</div></div></section>${faqSection()}`}
function intro(label,title,copy,num=''){return `<section class="page-intro"><div class="wrap"><div class="breadcrumb"><a href="/">The studio</a> / ${label}</div><div class="page-title-row"><div>${eyebrow(label)}<h1>${title}</h1><p>${copy}</p></div><span class="page-number">PORT & PIXEL / ${num}</span></div></div></section>`}
function servicePage(){return `${intro('Repair services','The right fix starts<br>with a closer look.','From the screen you see to the connections you rely on. Explore what we can help with, and know what to expect.','SERVICE INDEX')}<section class="section"><div class="wrap service-browser"><nav class="service-sidebar" aria-label="Repair categories">${services.map(s=>`<a href="#${s.id}">${s.name}</a>`).join('')}</nav><div>${services.map((s,i)=>`<article class="service-detail" id="${s.id}"><div class="service-title"><span aria-hidden="true">${s.icon}</span><div><div class="eyebrow" style="margin-bottom:7px">0${i+1} / ${s.tag}</div><h2>${s.name}</h2></div></div><p>${s.detail}</p>${i===0?image('screen-repair.jpg','Close-up of a technician working on an opened phone','service-editorial-photo'):''}<div class="service-info"><div><h4>What you might notice</h4><p>${s.symptoms}</p></div><div><h4>How we approach it</h4><p>${s.process}</p></div></div><p class="small"><strong>Cost & timing:</strong> ${s.factors}</p><div class="actions">${booking(s.id,'Book this service')}</div></article>`).join('')}<div class="notice"><h3>Symptoms don’t always tell the whole story.</h3><p>A phone that won’t charge might have a cable issue, a worn connector, or a deeper fault. An inspection helps confirm what needs attention. We explain the proposed work before you decide.</p></div></div></div></section><section class="section subtle-section"><div class="wrap">${eyebrow('Before your visit')}<h2>A little preparation helps.</h2><div class="care">${[['Back it up.','Make a recent backup where possible. Let us know if accessing your data is part of the problem.'],['Keep it personal.','Remove sensitive content where practical. Never include passwords or passcodes in your request.'],['Tell us the details.','Mention when the problem started, any drops or liquid exposure, and what you’ve already tried.']].map(([t,p])=>`<div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section>${faqSection('A little clarity before you book.')}`}
function accessories(){return `<section class="page-intro"><div class="wrap"><div class="breadcrumb"><a href="/">The studio</a> / Accessories</div><div class="catalog-hero"><div>${eyebrow('Considered essentials')}<h1>The everyday.<br>Well equipped.</h1><p>Protect it. Charge it. Make it yours. Explore useful additions to the device that goes everywhere with you.</p><p class="small">A curated selection for enquiry. Ask us about fit, current availability, and pricing.</p></div>${image('accessory-hero.jpg','A thoughtfully arranged collection of everyday phone accessories','catalog-hero-image',true)}</div></div></section><section class="section"><div class="wrap"><div class="catalog-toolbar"><div class="search-field"><label class="hidden" for="product-search">Search accessories</label><input type="search" id="product-search" placeholder="Search accessories…" aria-label="Search accessories"></div><select id="product-sort" aria-label="Sort accessories"><option value="featured">Featured selection</option><option value="az">Name: A–Z</option><option value="za">Name: Z–A</option></select></div><div class="category-filters" aria-label="Accessory categories">${['All essentials',...new Set(products.map(p=>p.category))].map((c,i)=>`<button class="chip" data-category="${c}" aria-pressed="${i===0}">${c}</button>`).join('')}</div><div id="catalog-count" class="catalog-count" aria-live="polite"></div><div class="catalog-grid" id="catalog"></div></div></section><section class="section" style="padding-top:0"><div class="wrap accessory-feature">${image('cable.jpg','USB-C connection cable arranged on a marble surface','product-image')}<div>${eyebrow('Less clutter. More connection.')}<h2>A better connection<br>starts with the basics.</h2><p>A cable that fits. A charger that suits your device. Build a practical setup around what you actually use.</p><a href="/contact?product=cable" class="text-link" style="margin-top:28px">Find your charging essential ${arrow}</a><p class="small" style="margin-top:24px">Check connector type and supported charging power before choosing.</p></div></div></section>`}
function pricing(){return `${intro('Pricing guide','Clarity comes<br>before the repair.','Your device model, the component needed, and the extent of damage all shape the cost. Start here to understand what goes into your estimate.','ESTIMATE NOTES')}<section class="section"><div class="wrap pricing-layout"><div class="pricing-select"><label for="price-service">What needs attention?</label><select id="price-service">${services.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select><label for="price-device">Your device category</label><select id="price-device"><option>Smartphone</option><option>Tablet</option><option>Other mobile device</option></select><p>Your repair estimate is tailored to your device. Share your model to discuss the scope and cost before agreeing to work.</p></div><div id="estimate-panel" aria-live="polite"></div></div></section><section class="section subtle-section"><div class="wrap">${eyebrow('What shapes an estimate')}<h2>More than a single part.</h2><p style="margin-top:18px;max-width:650px">These factors can contribute to a repair estimate. They are not necessarily charged separately; the proposed scope should make that clear.</p><div class="breakdown">${[['The component','Display type, battery design, and model-specific components can vary.'],['The work involved','Access, fitting, reassembly, and functional checks depend on the device.'],['The assessment','Diagnosis helps establish the cause and appropriate next steps.'],['The bigger picture','Frame damage, corrosion, and parts availability may affect the plan.']].map(([t,p],i)=>`<div><span>0${i+1} /</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section>${faqSection('Estimates, explained.',[['Why do similar phones have different repair costs?','Different models use different display technologies, component designs, and assembly methods. Parts availability can also vary, so a model-specific estimate is more useful than one general price.'],['Can the estimate change after inspection?','Yes. Inspection may reveal damage that could not be identified from the initial description. Ask for an updated estimate and agree to any additional work before it proceeds.'],['Will diagnosis be a separate charge?','Ask the shop to confirm any assessment fee and a device-specific repair estimate before you agree to service.'],['Does requesting an estimate commit me to a repair?','No. Preparing a request helps start a conversation. Repair work should only proceed after the scope and cost are agreed.']])}`}
function estimatePanel(){const s=services.find(s=>s.id===$('#price-service').value),device=$('#price-device').value;$('#estimate-panel').innerHTML=`<article class="estimate-card"><div class="panel-kicker"><span>${safe(device.toUpperCase())} / REPAIR GUIDE</span><span>${s.icon}</span></div><h2>${s.name}</h2><span class="estimate-status">Device-specific quotation</span><p>${s.detail}</p><dl><dt>Pricing status</dt><dd>Request an estimate for your exact device.</dd><dt>What may affect the cost</dt><dd>${s.factors}</dd><dt>Before you proceed</dt><dd>Final scope, component options, and timing are subject to assessment and your approval. ${device!=='Smartphone'?'Support for this device category must be confirmed.':''}</dd></dl>${booking(s.id,'Request an Estimate')}</article>`}
function contact(){const params=new URLSearchParams(location.search),product=products.find(p=>p.id===params.get('product')),service=services.find(s=>s.id===params.get('service'));return `${intro('Contact & booking','Let’s give your phone<br>its next chapter.','Tell us a little about your device and what’s going on. A helpful repair conversation starts with the details.','YOUR REPAIR REQUEST')}<section class="section"><div class="wrap contact-layout"><div><div id="form-container"><form class="booking-form" id="booking-form" novalidate><h2>${product?'Your accessory enquiry':'Your repair request'}</h2><p class="form-intro">${product?'Ask about compatibility, availability, and pricing.':'Share the details below. Your preferred visit is a request, subject to confirmation.'}</p>${product?`<div class="context-note"><strong>Enquiring about: ${product.name}</strong><p class="small">${product.attribute}</p></div>`:''}<div class="form-grid">${field('name','Full name','text','e.g. Alex Morgan',true)}${field('email','Email','email','you@example.com',true)}${field('phone','Phone number','tel','Your contact number',true)}${field('brand','Device brand','text','e.g. Apple, Samsung, Google',!product)}${field('model','Device model','text','e.g. iPhone 14',!product)}<div class="field"><label for="service">${product?'Enquiry type':'Repair service'} <span class="required">*</span></label><select id="service" name="service" required aria-describedby="service-error"><option value="">Choose a service</option>${services.map(s=>`<option value="${s.id}" ${s.id===service?.id?'selected':''}>${s.name}</option>`).join('')}<option value="unsure">Not sure — help me choose</option><option value="accessory" ${product?'selected':''}>Accessory enquiry</option></select><span class="field-error" id="service-error"></span></div><div class="field full"><label for="description">${product?'Your question':'Description of the issue'} <span class="required">*</span></label><textarea id="description" name="description" required minlength="10" aria-describedby="description-error" placeholder="${product?'Tell us your device model and what you’d like to know.':'What happens, when did it start, and what have you tried?'}"></textarea><span class="field-error" id="description-error"></span></div>${field('date','Preferred visit date','date','',false)}<div class="field"><label for="time">Preferred time window <span class="muted">(optional)</span></label><select id="time" name="time"><option value="">No preference</option><option>Morning</option><option>Afternoon</option><option>Late afternoon</option></select><p class="field-hint">Visit timing is subject to shop confirmation.</p></div><div class="field full"><label for="notes">Additional notes <span class="muted">(optional)</span></label><textarea id="notes" name="notes" placeholder="Anything else that would help us understand your request?" style="min-height:80px"></textarea></div></div><label class="consent" for="consent"><input type="checkbox" id="consent" name="consent" required aria-describedby="consent-error"><span>I understand that this form prepares a local request, and no information is sent to the shop without a connected submission service. I have read the <button type="button" class="privacy-open" style="padding:0;border:0;background:none;text-decoration:underline;color:var(--brand)">privacy information</button>.</span></label><span class="field-error" id="consent-error"></span><div class="actions"><button type="submit" class="btn">${product?'Prepare Item Enquiry':'Submit Repair Request'} ${arrow}</button></div><p class="form-note">${business.submissionEndpoint?'Your request will be sent using the configured submission service.':'This form currently prepares a request on your device. It does not send it or confirm an appointment. After validation, you can review and download a copy.'}</p><div id="submit-error" role="alert"></div></form></div></div><aside class="contact-aside">${eyebrow('Before you stop by')}<h3>A little preparation.<br>A smoother visit.</h3><p>Your phone does a lot. A few simple steps help you get it ready for attention.</p><ol class="prepare-list"><li><span>01</span>Back up your phone, if you can.</li><li><span>02</span>Note the model and describe what’s changed.</li><li><span>03</span>Bring the charging cable if charging is the issue.</li><li><span>04</span>Keep passwords and sensitive information out of your request.</li></ol><p class="small">Estimates and visit windows are subject to confirmation. Don’t make a journey until your visit is agreed.</p>${business.address?`<p>${safe(business.address)}</p>`:''}${business.phone?`<p><a href="tel:${safe(business.phone)}">${safe(business.phone)}</a></p>`:''}${business.hours?`<p>${safe(business.hours)}</p>`:''}</aside></div></section>`}
function field(name,label,type,placeholder,required){return `<div class="field"><label for="${name}">${label} ${required?'<span class="required">*</span>':'<span class="muted">(optional)</span>'}</label><input id="${name}" name="${name}" type="${type}" ${required?'required':''} placeholder="${placeholder}" ${name==='date'?`min="${localDate()}"`:''} ${['name','email','phone'].includes(name)?`autocomplete="${{name:'name',email:'email',phone:'tel'}[name]}"`:''} aria-describedby="${name}-error"><span class="field-error" id="${name}-error"></span></div>`}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
