let menuOpen=false;const menuToggle=$('.menu-toggle'),mobilePanel=$('.mobile-panel');
function setMenu(open){menuOpen=open;mobilePanel.classList.toggle('open',open);mobilePanel.inert=!open;menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');menuToggle.textContent=open?'×':'☰';document.body.style.overflow=open?'hidden':'';if(!open&&mobilePanel.contains(document.activeElement))menuToggle.focus();}
menuToggle.addEventListener('click',()=>setMenu(!menuOpen));
document.addEventListener('click',e=>{if(menuOpen&&!e.target.closest('.header'))setMenu(false);const home=$('.home-menu');if(home.open&&!e.target.closest('.home-menu'))home.open=false;});
$$('a',mobilePanel).forEach(a=>a.addEventListener('click',()=>setMenu(false)));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){setMenu(false);$('.home-menu').open=false;}if(e.key==='Tab'&&menuOpen){const nodes=$$('a,button,summary',mobilePanel).filter(el=>el.getClientRects().length),all=[menuToggle,...nodes];if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0].focus()}}});
matchMedia('(min-width:921px)').addEventListener('change',e=>{if(e.matches)setMenu(false)});
function syncPreferences(){$$('.theme-toggle').forEach(b=>{b.setAttribute('aria-pressed',String(document.documentElement.dataset.theme==='dark'));b.setAttribute('aria-label',document.documentElement.dataset.theme==='dark'?'Switch to light mode':'Switch to dark mode')});$$('.direction-btn').forEach(b=>{b.textContent=document.documentElement.dir==='rtl'?'LTR':'RTL';b.setAttribute('aria-label',`Switch to ${document.documentElement.dir==='rtl'?'left-to-right':'right-to-left'} reading direction`)});}
$$('.theme-toggle').forEach(b=>b.addEventListener('click',()=>{const v=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=v;try{localStorage.setItem('pp-theme',v)}catch{}syncPreferences()}));
$$('.direction-btn').forEach(b=>b.addEventListener('click',()=>{const v=document.documentElement.dir==='rtl'?'ltr':'rtl';document.documentElement.dir=v;try{localStorage.setItem('pp-dir',v)}catch{}syncPreferences()}));syncPreferences();
