$$('.privacy-open').forEach(b=>b.addEventListener('click',()=>$('#privacy-modal').showModal()));
$$('dialog').forEach(d=>{ $('.modal-close',d).addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});});
$$('[data-issue]').forEach(b=>b.addEventListener('click',()=>{$$('[data-issue]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));$('#issue-panel').innerHTML=issuePanel(services.find(s=>s.id===b.dataset.issue));}));
function wireProducts(){$$('[data-product]').forEach(b=>b.addEventListener('click',()=>{const p=products.find(p=>p.id===b.dataset.product);$('#modal-content').innerHTML=`<div class="modal-grid">${image(p.image,p.name,'product-image',true)}<div>${eyebrow(p.category)}<h2 style="font-size:27px">${p.name}</h2><p>${p.description}</p><p class="small">Pricing and availability confirmed on enquiry.</p><a class="btn" href="/contact?product=${p.id}">Enquire about this item ${arrow}</a></div></div>`;$('#detail-modal').showModal()}))}
let activeCategory='All essentials';
function renderCatalog(){const query=$('#product-search').value.trim().toLowerCase();let list=products.filter(p=>(activeCategory==='All essentials'||p.category===activeCategory)&&`${p.name} ${p.attribute} ${p.category}`.toLowerCase().includes(query));const sort=$('#product-sort').value;if(sort!=='featured')list.sort((a,b)=>sort==='az'?a.name.localeCompare(b.name):b.name.localeCompare(a.name));$('#catalog-count').textContent=`${list.length} ${list.length===1?'essential':'essentials'} · Compatibility, prices, and availability confirmed on enquiry`;$('#catalog').innerHTML=list.length?list.map(productCard).join(''):'<div class="empty-state"><h3>No matches just yet.</h3><p>Try a different search or browse all essentials.</p><button class="btn secondary" id="reset-products" style="margin-top:20px">Reset filters</button></div>';$('#reset-products')?.addEventListener('click',()=>{activeCategory='All essentials';$('#product-search').value='';$$('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===activeCategory)));renderCatalog()});wireProducts()}
if(path==='/accessories'){$('#product-search').addEventListener('input',renderCatalog);$('#product-sort').addEventListener('change',renderCatalog);$$('[data-category]').forEach(b=>b.addEventListener('click',()=>{activeCategory=b.dataset.category;$$('[data-category]').forEach(el=>el.setAttribute('aria-pressed',String(b===el)));renderCatalog()}));renderCatalog()}else wireProducts();
const symptoms={screen:['Cracked glass','Display does not respond','Flickering or black spots'],battery:['Drains quickly','Unexpected shutdowns','Does not hold charge'],charging:['No charging response','Loose cable connection','Charging cuts in and out'],software:['Slow performance','Apps keep crashing','Repeated restarts'],camera:['Photos look blurry','Camera preview is black','Lens is damaged'],audio:['Quiet speaker','Microphone not heard','Distorted playback']};
function finderUpdate(reset=false){const id=$('#finder-problem').value,s=services.find(s=>s.id===id);if(reset)$('#finder-symptom').innerHTML=symptoms[id].map(t=>`<option>${t}</option>`).join('');const params=new URLSearchParams({service:id,device:$('#finder-device').value,symptom:$('#finder-symptom').value});$('#finder-result').className='finder-result';$('#finder-result').innerHTML=`<div><strong>A useful place to start: ${s.name}</strong><p>For your ${safe($('#finder-device').value.toLowerCase())}: ${safe($('#finder-symptom').value.toLowerCase())}. An assessment will help confirm the cause.</p></div><a class="btn" href="/contact?${params.toString()}">Continue to booking ${arrow}</a>`;}
if(path==='/home-2'){$('#finder-problem').addEventListener('change',()=>finderUpdate(true));$('#finder-device').addEventListener('change',()=>finderUpdate());$('#finder-symptom').addEventListener('change',()=>finderUpdate());finderUpdate(true)}
if(path==='/pricing'){const selected=new URLSearchParams(location.search).get('service');if(services.some(s=>s.id===selected))$('#price-service').value=selected;$('#price-service').addEventListener('change',estimatePanel);$('#price-device').addEventListener('change',estimatePanel);estimatePanel()}
let requestSummary='';
function setupForm(){const form=$('#booking-form');if(!form)return;const params=new URLSearchParams(location.search);const device=params.get('device'),symptom=params.get('symptom');if(device||symptom)$('#description').value=[device?`Device category: ${device}`:'',symptom?`Symptom: ${symptom}`:''].filter(Boolean).join('\n');form.addEventListener('submit',async e=>{e.preventDefault();let firstInvalid=null;for(const input of $$('input,select,textarea',form)){let error='';if(input.required&&(input.type==='checkbox'?!input.checked:!input.value.trim()))error=input.type==='checkbox'?'Please acknowledge how this request is handled.':'Please complete this field.';else if(input.name==='email'&&input.value&&!input.validity.valid)error='Enter a valid email address, such as name@example.com.';else if(input.name==='phone'&&input.value&&!/^[+\d\s().-]{7,25}$/.test(input.value))error='Enter a phone number with 7–25 characters using digits and normal phone symbols.';else if(input.name==='phone'&&input.value.replace(/\D/g,'').length<7)error='Enter at least 7 digits for your phone number.';else if(input.name==='description'&&input.value.trim().length<10)error='Add at least 10 characters so the issue is clear.';else if(input.name==='date'&&input.value&&input.value<localDate())error='Choose today or a future date.';const el=$(`#${input.name}-error`);if(el)el.textContent=error;input.setAttribute('aria-invalid',String(Boolean(error)));if(error&&!firstInvalid)firstInvalid=input;}if(firstInvalid){firstInvalid.focus();return;}const data=Object.fromEntries(new FormData(form));data.product=products.find(p=>p.id===params.get('product'))?.name||'';const service=services.find(s=>s.id===data.service)?.name||(data.service==='accessory'?'Accessory enquiry':'Help choosing a service');requestSummary=[`PORT & PIXEL — ${business.submissionEndpoint?'REQUEST':'LOCAL REQUEST COPY (NOT SENT)'}`,`Name: ${data.name}`,`Email: ${data.email}`,`Phone: ${data.phone}`,`Device: ${data.brand} ${data.model}`,`Request: ${service}`,data.product?`Accessory: ${data.product}`:'',`Details: ${data.description}`,`Preferred date: ${data.date||'To discuss'}`,`Preferred time: ${data.time||'To discuss'}`,data.notes?`Notes: ${data.notes}`:''].filter(Boolean).join('\n');let sent=false;if(business.submissionEndpoint){const btn=$('[type=submit]',form);btn.disabled=true;btn.textContent='Sending request…';try{const response=await fetch(business.submissionEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!response.ok)throw new Error('Request failed');sent=true;}catch{$('#submit-error').innerHTML='<p class="field-error" style="margin-top:15px">Your request could not be sent. Please try again. Your entries are still here.</p>';btn.disabled=false;btn.textContent='Submit Repair Request';return;}}form.classList.add('hidden');const result=document.createElement('div');result.className='success';result.setAttribute('tabindex','-1');result.innerHTML=`<h3>${sent?'Your request has been sent.':'Your request is ready to review.'}</h3><p>${sent?'Your preferred visit still needs confirmation from the shop.':'This copy stays on your device. It has not been sent to the shop, and no appointment has been booked. Download it for your records, or edit the details below.'}</p><pre>${safe(requestSummary)}</pre><div class="actions"><button class="btn" id="download-request">Download request ↓</button><button class="btn secondary" id="edit-request">Edit details</button></div>`;$('#form-container').append(result);result.focus();$('#download-request').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([requestSummary],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='port-and-pixel-request.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});$('#edit-request').addEventListener('click',()=>{result.remove();form.classList.remove('hidden');$('#name').focus()});});}
if(path==='/contact')setupForm();
